package plates.core.values

import plates.core.theme.PlateTheme
import plates.core.validators.PlateValidator

/** One plate a country issues, ready to show, render or parse: a spec with the theme, panel and validator it goes with. */
public class PlateType(
    public val id: String,
    /** English name for a picker, e.g. `Civil`. */
    public val label: String,
    public val spec: PlateSpec,
    /** A plausible plate, one value per slot: draw it as a hint, or use it in tests. */
    public val sampleValues: List<String?>,
    public val theme: PlateTheme? = null,
    /** Set when this type is printed with another panel than the spec's own. */
    public val country: PlateCountry? = null,
    public val validator: PlateValidator? = null,
    public val note: String? = null,
) {
    override fun toString(): String = "PlateType($id)"
}
